Texture2D<float4> image : register(t0);
Texture1D<float4> curve : register(t1);
SamplerState linear_clamp : register(s0);
float4 plain(float4 position : SV_Position, float2 uv : TEXCOORD) : SV_Target {
    return image.SampleLevel(linear_clamp, uv, 0);
}
float4 curved(float4 position : SV_Position, float2 uv : TEXCOORD) : SV_Target {
    float4 input = image.SampleLevel(linear_clamp, uv, 0);
    float3 at = saturate(input.rgb) * 1024.0;
    int3 low = int3(at); int3 high = min(low + 1, 1024);
    float3 t = frac(at);
    float r = lerp(curve.Load(int2(low.r, 0)).r, curve.Load(int2(high.r, 0)).r, t.r);
    float g = lerp(curve.Load(int2(low.g, 0)).g, curve.Load(int2(high.g, 0)).g, t.g);
    float b = lerp(curve.Load(int2(low.b, 0)).b, curve.Load(int2(high.b, 0)).b, t.b);
    return float4(r, g, b, input.a);
}

cbuffer Detile : register(b0) {
    uint element, width, height, depth, tiles_x, tiles_y, row_pitch, slice_pitch, tables_at, pattern_at, units_x, shift;
};
StructuredBuffer<uint> source : register(t0);
RWStructuredBuffer<uint> output : register(u0);
uint offset_of(uint x, uint y, uint z) {
    uint within = (1u << shift) - 1;
    return source[tables_at + (z * tiles_y + (y >> shift)) * tiles_x + (x >> shift)] +
           source[pattern_at + ((y & within) << 3) + (x & within)];
}
[numthreads(64, 1, 1)]
void main(uint3 id : SV_DispatchThreadID) {
    uint unit = min(id.x, units_x - 1);
    uint row = id.z * slice_pitch + id.y * row_pitch;
    if (element >= 4) {
        uint from = offset_of(unit, id.y, id.z) >> 2;
        uint to = (row + unit * element) >> 2;
        if (id.x < units_x)
            for (uint word = 0; word < element / 4; ++word)
                output[to + word] = source[from + word];
        return;
    }
    uint per = 4 / element;
    uint bits = element * 8;
    uint mask = (1u << bits) - 1;
    uint value = 0;
    for (uint i = 0; i < per; ++i) {
        // A row's last word may hold fewer elements: a place past the row
        // reads the row's last element and adds nothing.
        uint x = unit * per + i;
        uint at = offset_of(min(x, width - 1), id.y, id.z);
        uint texel = (source[at >> 2] >> ((at & 3) * 8)) & mask;
        value |= (x < width ? texel : 0) << (i * bits);
    }
    if (id.x < units_x) output[(row >> 2) + unit] = value;
}

